:root {
    --layout-max-width: 100vw;
    --layout-news-columns: none;
    --layout-card-gap: 10vw;
    --layout-card-direction: row;
    --layout-animation-style: perspective-swing;
    --card-width: 75vw;
    --card-aspect: 16 / 9;
}

#news-container {
    display: flex;
    flex-direction: var(--layout-card-direction);
    gap: var(--layout-card-gap);
    padding: 0 12.5vw 10vh;
    overflow-x: auto;
    overflow-y: hidden;
    scroll-snap-type: x mandatory;
    scroll-behavior: smooth;
    perspective: 2000px;
    height: 80vh;
    align-items: center;
    -webkit-overflow-scrolling: touch;
}

#news-container::-webkit-scrollbar {
    height: 4px;
}

#news-container::-webkit-scrollbar-thumb {
    background: var(--morpho-accent-gradient);
}

.news-card {
    flex: 0 0 var(--card-width);
    aspect-ratio: var(--card-aspect);
    position: relative;
    scroll-snap-align: center;
    background: transparent;
    display: flex;
    flex-direction: column;
    justify-content: flex-end;
    transform-style: preserve-3d;

    /* Scroll-driven animation for 3D effect */
    view-timeline-name: --card-scroll;
    view-timeline-axis: inline;
    animation: var(--layout-animation-style) linear both;
    animation-timeline: --card-scroll;
}

.news-card-inner {
    position: relative;
    width: 100%;
    height: 100%;
    background: var(--morpho-bg-primary);
    border: 1px solid var(--morpho-accent-primary);
    padding: 4rem;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    box-shadow: 20px 20px 60px rgba(0,0,0,0.3);
    overflow: hidden;
}

